// Generate a valid timespec with normalized tv_nsec in [0, 999,999,999].
struct timespec ts;
// Keep seconds within a reasonable 32-bit range to avoid overflows in conversions.
long sec = static_cast<long>(*FUZZ_PARAM(unsigned int));
unsigned int nsec_raw = *FUZZ_PARAM(unsigned int);
long nsec = static_cast<long>(nsec_raw % 1000000000u);
ts.tv_sec = sec;
ts.tv_nsec = nsec;
// Call the target conversion function.
perfetto::base::TimeNanos tn = perfetto::base::FromPosixTimespec(ts);
// Produce a persistent output object holding the result.
perfetto::base::TimeNanos *tn_out = new perfetto::base::TimeNanos(tn);
// No additional properties to assert here; correctness depends on implementation.

// Constrain the sleep interval to keep fuzzing fast and avoid long stalls.
unsigned int interval_us = (*FUZZ_PARAM(unsigned int) % 101u); // [0, 100] us
// Invoke the sleep with the constrained interval.
perfetto::base::SleepMicroseconds(interval_us);
// No outputs; function has no return and no persistent state.

// Initialize any timekeeping facilities. The function is assumed to be safe to call.
perfetto::base::InitializeTime();
// No outputs; this is a one-shot initializer with no direct return value.

// Obtain wall time twice to validate monotonic non-decreasing behavior.
perfetto::base::TimeNanos t1 = perfetto::base::GetWallTimeNs();
perfetto::base::TimeNanos t2 = perfetto::base::GetWallTimeNs();
FUZZ_ASSERT(t2.count() >= t1.count(), "GetWallTimeNs must be monotonic non-decreasing");
// Persist the first measurement as an output object.
perfetto::base::TimeNanos *t1_out = new perfetto::base::TimeNanos(t1);

// Call twice and assert non-decreasing CPU time for the calling thread.
perfetto::base::TimeNanos c1 = perfetto::base::GetThreadCPUTimeNs();
perfetto::base::TimeNanos c2 = perfetto::base::GetThreadCPUTimeNs();
FUZZ_ASSERT(c2.count() >= c1.count(), "Thread CPU time must be non-decreasing");
perfetto::base::TimeNanos *cpu_out = new perfetto::base::TimeNanos(c2);

// Get raw monotonic time twice and assert non-decreasing.
perfetto::base::TimeNanos r1 = perfetto::base::GetWallTimeRawNs();
perfetto::base::TimeNanos r2 = perfetto::base::GetWallTimeRawNs();
FUZZ_ASSERT(r2.count() >= r1.count(), "Raw monotonic time must be non-decreasing");
perfetto::base::TimeNanos *raw_out = new perfetto::base::TimeNanos(r2);

// Get boot time twice and assert non-decreasing.
perfetto::base::TimeNanos b1 = perfetto::base::GetBootTimeNs();
perfetto::base::TimeNanos b2 = perfetto::base::GetBootTimeNs();
FUZZ_ASSERT(b2.count() >= b1.count(), "Boot time (ns) must be non-decreasing");
perfetto::base::TimeNanos *boot_ns_out = new perfetto::base::TimeNanos(b2);

// Get boot time in seconds (cast from ns internally). Multiple calls should be non-decreasing.
perfetto::base::TimeSeconds s1 = perfetto::base::GetBootTimeS();
perfetto::base::TimeSeconds s2 = perfetto::base::GetBootTimeS();
FUZZ_ASSERT(s2.count() >= s1.count(), "Boot time (s) must be non-decreasing");
perfetto::base::TimeSeconds *boot_s_out = new perfetto::base::TimeSeconds(s2);

// Get boot time in milliseconds; assert non-decreasing across successive calls.
perfetto::base::TimeMillis m1 = perfetto::base::GetBootTimeMs();
perfetto::base::TimeMillis m2 = perfetto::base::GetBootTimeMs();
FUZZ_ASSERT(m2.count() >= m1.count(), "Boot time (ms) must be non-decreasing");
perfetto::base::TimeMillis *boot_ms_out = new perfetto::base::TimeMillis(m2);

// Get monotonic wall time in milliseconds twice and assert non-decreasing.
perfetto::base::TimeMillis w1 = perfetto::base::GetWallTimeMs();
perfetto::base::TimeMillis w2 = perfetto::base::GetWallTimeMs();
FUZZ_ASSERT(w2.count() >= w1.count(), "Wall time (ms) must be non-decreasing");
perfetto::base::TimeMillis *wt_ms_out = new perfetto::base::TimeMillis(w2);

// Get monotonic wall time in seconds twice and assert non-decreasing.
perfetto::base::TimeSeconds s1 = perfetto::base::GetWallTimeS();
perfetto::base::TimeSeconds s2 = perfetto::base::GetWallTimeS();
FUZZ_ASSERT(s2.count() >= s1.count(), "Wall time (s) must be non-decreasing");
perfetto::base::TimeSeconds *wt_s_out = new perfetto::base::TimeSeconds(s2);

// Convert the provided TimeMillis duration to a timespec.
// The input is provided by the fuzzer runtime; do not redeclare it.
perfetto::base::TimeMillis tm_val = *tm_in;
struct timespec ts = perfetto::base::ToPosixTimespec(tm_val);
// Validate normalization: tv_nsec should be within [0, 999,999,999].
FUZZ_ASSERT(ts.tv_nsec >= 0 && ts.tv_nsec < 1000000000L, "timespec tv_nsec must be normalized");
// Input duration remains valid; return it as output to keep it in the pool.

// Generate a random format string. It may contain arbitrary bytes; implementation should handle/ignore invalid tokens.
std::string fmt = FUZZ_PARAM_STR();
// Call the formatter. The result is intentionally discarded but exercises the code path.
std::string out = perfetto::base::GetTimeFmt(fmt);
// No assertions about content since formatting rules are implementation-defined.

// Build a UTC struct tm with sensible ranges to avoid undefined behavior.
struct tm tms;
// Initialize fields with constrained values.
tms.tm_year = static_cast<int>(*FUZZ_PARAM(unsigned int) % 300) + 0; // years since 1900; 0..299 (~1900..2199)
tms.tm_mon  = static_cast<int>(*FUZZ_PARAM(unsigned int) % 12);     // 0..11
// Day of month 1..31, but struct tm expects 1..31 in tm_mday.
tms.tm_mday = static_cast<int>(*FUZZ_PARAM(unsigned int) % 31) + 1;  // 1..31
// Time components.
tms.tm_hour = static_cast<int>(*FUZZ_PARAM(unsigned int) % 24);      // 0..23
tms.tm_min  = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);      // 0..59
tms.tm_sec  = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);      // 0..59
// Weekday/year day can be left unspecified; set to 0.
tms.tm_wday = 0;
tms.tm_yday = 0;
// Force UTC (no DST adjustment).
tms.tm_isdst = 0;
// Invoke TimeGm; platform should provide an implementation (non-NaCl).
(void)perfetto::base::TimeGm(&tms);
// No outputs.

// Generate date/time components within documented constraints.
int year  = static_cast<int>(*FUZZ_PARAM(unsigned int) % 300) + 1900; // >= 1900
int month = static_cast<int>(*FUZZ_PARAM(unsigned int) % 12) + 1;     // 1..12
int day   = static_cast<int>(*FUZZ_PARAM(unsigned int) % 31) + 1;     // 1..31
int h     = static_cast<int>(*FUZZ_PARAM(unsigned int) % 24);         // 0..23
int m     = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);         // 0..59
int s     = static_cast<int>(*FUZZ_PARAM(unsigned int) % 60);         // 0..59
// Invoke MkTime which internally constructs tm and calls TimeGm.
(void)perfetto::base::MkTime(year, month, day, h, m, s);
// No outputs.

// Query the timezone offset from UTC in minutes. The result may be empty.
std::optional<int32_t> off = perfetto::base::GetTimezoneOffsetMins();
// If present, loosely bound the value to a plausible range [-14h, +14h] in minutes.
if (off.has_value()) {
  int32_t v = *off;
  // Use a property assertion for sanity of the typical timezone range.
  FUZZ_ASSERT(v >= -14 * 60 && v <= 14 * 60, "Timezone offset should be within plausible bounds");
}
// No outputs.
